 */
const generateChatcmplId = () => {
  const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
  let id = "chatcmpl-";
  for (let i = 0; i < 29; i++) {
    id += chars[Math.floor(Math.random() * chars.length)];
  }
  return id;
};

/**
 * 构造符合 OpenAI 格式的 SSE 消息块
 *
 * @param {string} deltaContent 要发送的文本内容
 * @returns {string} 格式化后的 SSE 消息数据块
 */
function createSSEChunk(deltaContent) {
  const data = {
    id: generateChatcmplId(),
    object: "chat.completion.chunk",
    created: Math.floor(Date.now() / 1000),
    model: userConfig.thinking_model,
    choices: [
      {
        delta: { content: deltaContent },
        index: 0,
        finish_reason: null,
      },
    ],
  };
  return `data: ${JSON.stringify(data)}\n\n`;
}

/**
 * 构造增强后的基础模型请求体
 *
 * 说明:
 *  1. 对 system 消息进行 XML 标签封装，并附加截断的思考内容；
 *  2. 在 user 消息之前添加引导文本，提示基础模型参考思考过程；
 *  3. 指定使用基础模型进行推理。
 *
 * @param {Object} normalizedRequestBody 标准化后的请求体对象
 * @param {string} truncatedContent 从思考模型响应中截取的思考内容
 * @returns {Object} 增强后的基础模型请求体
 */
function buildThoughtfulRequest(normalizedRequestBody, truncatedContent) {
  const requestBody = structuredClone(normalizedRequestBody);
  const tag = userConfig.xmlSystemTag;
  const originalSystem = requestBody.messages[0].content;

  // 使用 XML 标签包装 system 消息，并附加截断的思考内容
  requestBody.messages[0].content = `<${tag}>${originalSystem}</${tag}>\n${truncatedContent}`;

  // 在 user 消息前添加引导文本
  const insertionText = userConfig.introThought;
  const lastIndex = requestBody.messages.length - 1;
  requestBody.messages[lastIndex].content =
    insertionText + requestBody.messages[lastIndex].content;

  requestBody.model = userConfig.base_model;
  return requestBody;
}

