    try {
      const baseRes = await fetch(userConfig.base_LLM_url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${userConfig.base_LLM_authkey}`,
        },
        body: JSON.stringify(directPayload),
      });
      return new Response(baseRes.body, {
        status: baseRes.status,
        headers: baseRes.headers,
      });
    } catch (err) {
      return new Response(
        JSON.stringify({
          error: "Error contacting base model",
          details: err.toString(),
        }),
        { status: 500, headers: { "Content-Type": "application/json" } }
      );
    }
  }

  // 流式请求处理：先调用思考模型，再调用基础模型，最后返回合并的 SSE 响应流
  const normalized = openai_messages_normalizer(clientRequestPayload);
  const thinkingRequest = structuredClone(normalized);
  thinkingRequest.model = userConfig.thinking_model;
  // 在 system 消息前添加思考模型前缀
  thinkingRequest.messages[0].content =
    userConfig.thinking_LLM_prefix + thinkingRequest.messages[0].content;

  let thinkingResponse;
  try {
    thinkingResponse = await fetch(userConfig.thinking_LLM_url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        // 使用客户端 token 调用思考模型
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify(thinkingRequest),
    });
  } catch (err) {
    return new Response(
      JSON.stringify({
        error: "Error contacting thinking model",
        details: err.toString(),
      }),
      { status: 500, headers: { "Content-Type": "application/json" } }
    );
  }

  // 如果思考模型返回状态异常，则直接返回该响应
  if (thinkingResponse.status !== 200) {
    return thinkingResponse;
  }

  if (userConfig.showThinking) {
    // 流式处理：实时传输思考过程并转发基础模型响应流
    return new Response(
      new ReadableStream({
        async start(controller) {
          // 阶段1：处理思考模型 SSE 流的响应，同时累计截断后的思考文本
          const truncated = await processThinkingStream(
            thinkingResponse.body.getReader(),
            controller
          );
          if (userConfig.debug) {
            console.log("思考模型截断内容:", truncated);
          }
          // 插入额外 SSE 消息块（符合 OpenAI 格式）
          controller.enqueue(new TextEncoder().encode(createSSEChunk("\n\n")));

          // 阶段2：构造基础模型请求，并转发 SSE 响应流
          const baseRequest = buildThoughtfulRequest(normalized, truncated);
          if (userConfig.debug) {
            console.log("基础模型请求体:", JSON.stringify(baseRequest, null, 2));
          }
          try {
            const baseRes = await fetchBaseModel(baseRequest);
            const baseReader = baseRes.body.getReader();
            while (true) {
              const { value, done } = await baseReader.read();
              if (done) break;
              controller.enqueue(value);
            }
          } catch (err) {
            controller.error(
              new TextEncoder().encode(
                JSON.stringify({
                  error: "Error contacting base model",
                  details: err.toString(),
                })
              )
            );
          }
          controller.close();
        },
      }),
      { headers: { "Content-Type": "text/event-stream" } }
    );
  } else {
    // 静默模式：先完整处理思考模型响应，再调用基础模型
    const truncated = await processThinkingStream(thinkingResponse.body.getReader());
    if (userConfig.debug) {
      console.log("思考模型截断内容:", truncated);
    }
    const baseRequest = buildThoughtfulRequest(normalized, truncated);
    if (userConfig.debug) {
      console.log("基础模型请求体:", JSON.stringify(baseRequest, null, 2));
    }
    return fetchBaseModel(baseRequest);
  }
}

